import type { ReactElement } from "react"

type DetectedComponentKind = "bga" | "qfp" | "qfp_thermalpad" | "soic"

interface TopologyPairProps {
  name: string
  topKind: DetectedComponentKind
  bottomKind: DetectedComponentKind
}

interface DetectedComponentProps {
  kind: DetectedComponentKind
  name: string
  pcbY: number
}

interface PadProps {
  name: string
  x: number
  y: number
  width: number
  height: number
}

const RectPad = ({ name, x, y, width, height }: PadProps): ReactElement => (
  <smtpad
    name={name}
    portHints={[name]}
    pcbX={x}
    pcbY={y}
    layer="top"
    shape="rect"
    width={width}
    height={height}
  />
)

const BgaFootprint = (): ReactElement => (
  <footprint>
    {Array.from({ length: 4 }).flatMap((_, row) =>
      Array.from({ length: 4 }).map((_, col) => (
        <RectPad
          key={`bga_${row}_${col}`}
          name={`B${row + 1}_${col + 1}`}
          x={(col - 1.5) * 0.7}
          y={(row - 1.5) * 0.7}
          width={0.36}
          height={0.36}
        />
      )),
    )}
  </footprint>
)

const QfpFootprint = ({ thermalPad }: { thermalPad: boolean }): ReactElement => {
  const sidePads = [-0.8, 0, 0.8]

  return (
    <footprint>
      {sidePads.map((x, index) => (
        <RectPad
          key={`top_${index}`}
          name={`T${index + 1}`}
          x={x}
          y={1.6}
          width={0.28}
          height={0.8}
        />
      ))}
      {sidePads.map((x, index) => (
        <RectPad
          key={`bottom_${index}`}
          name={`B${index + 1}`}
          x={x}
          y={-1.6}
          width={0.28}
          height={0.8}
        />
      ))}
      {sidePads.map((y, index) => (
        <RectPad
          key={`left_${index}`}
          name={`L${index + 1}`}
          x={-1.6}
          y={y}
          width={0.8}
          height={0.28}
        />
      ))}
      {sidePads.map((y, index) => (
        <RectPad
          key={`right_${index}`}
          name={`R${index + 1}`}
          x={1.6}
          y={y}
          width={0.8}
          height={0.28}
        />
      ))}
      {thermalPad && (
        <RectPad name="THERMAL" x={0} y={0} width={1.2} height={1.2} />
      )}
    </footprint>
  )
}

const SoicFootprint = (): ReactElement => {
  const rowPads = [-1.5, -0.5, 0.5, 1.5]

  return (
    <footprint>
      {rowPads.map((y, index) => (
        <RectPad
          key={`left_${index}`}
          name={`L${index + 1}`}
          x={-1.4}
          y={y}
          width={0.55}
          height={0.28}
        />
      ))}
      {rowPads.map((y, index) => (
        <RectPad
          key={`right_${index}`}
          name={`R${index + 1}`}
          x={1.4}
          y={y}
          width={0.55}
          height={0.28}
        />
      ))}
    </footprint>
  )
}

const DetectedComponent = ({
  kind,
  name,
  pcbY,
}: DetectedComponentProps): ReactElement => {
  const footprint =
    kind === "bga" ? (
      <BgaFootprint />
    ) : kind === "qfp" ? (
      <QfpFootprint thermalPad={false} />
    ) : kind === "qfp_thermalpad" ? (
      <QfpFootprint thermalPad={true} />
    ) : (
      <SoicFootprint />
    )

  return (
    <chip
      name={name}
      pcbX={0}
      pcbY={pcbY}
      footprint={footprint}
      noSchematicRepresentation
    />
  )
}

const TopologyPair = ({
  name,
  topKind,
  bottomKind,
}: TopologyPairProps): ReactElement => (
  <board title={name} width="10mm" height="12mm">
    <DetectedComponent kind={topKind} name={`${name}_top`} pcbY={4} />
    <DetectedComponent kind={bottomKind} name={`${name}_bottom`} pcbY={-4} />
  </board>
)

export const topology_pair_bga_bga = (): ReactElement => (
  <TopologyPair name="topology_pair_bga_bga" topKind="bga" bottomKind="bga" />
)

export const topology_pair_bga_qfp = (): ReactElement => (
  <TopologyPair name="topology_pair_bga_qfp" topKind="bga" bottomKind="qfp" />
)

export const topology_pair_bga_qfp_thermalpad = (): ReactElement => (
  <TopologyPair
    name="topology_pair_bga_qfp_thermalpad"
    topKind="bga"
    bottomKind="qfp_thermalpad"
  />
)

export const topology_pair_bga_soic = (): ReactElement => (
  <TopologyPair name="topology_pair_bga_soic" topKind="bga" bottomKind="soic" />
)

export const topology_pair_qfp_qfp = (): ReactElement => (
  <TopologyPair name="topology_pair_qfp_qfp" topKind="qfp" bottomKind="qfp" />
)

export const topology_pair_qfp_qfp_thermalpad = (): ReactElement => (
  <TopologyPair
    name="topology_pair_qfp_qfp_thermalpad"
    topKind="qfp"
    bottomKind="qfp_thermalpad"
  />
)

export const topology_pair_qfp_soic = (): ReactElement => (
  <TopologyPair name="topology_pair_qfp_soic" topKind="qfp" bottomKind="soic" />
)

export const topology_pair_qfp_thermalpad_qfp_thermalpad =
  (): ReactElement => (
    <TopologyPair
      name="topology_pair_qfp_thermalpad_qfp_thermalpad"
      topKind="qfp_thermalpad"
      bottomKind="qfp_thermalpad"
    />
  )

export const topology_pair_qfp_thermalpad_soic = (): ReactElement => (
  <TopologyPair
    name="topology_pair_qfp_thermalpad_soic"
    topKind="qfp_thermalpad"
    bottomKind="soic"
  />
)

export const topology_pair_soic_soic = (): ReactElement => (
  <TopologyPair name="topology_pair_soic_soic" topKind="soic" bottomKind="soic" />
)

export default topology_pair_bga_bga

